from vs import corpus,ivtff
from collections import Counter,defaultdict
import math,random,json
CHARS='acdefgiklmnopqrsy' # 17 plus other => 18
assert len(CHARS)==17 and len(set(CHARS))==17
K=18

def cls(w):return CHARS.index(w[0]) if w[0] in CHARS else 17

def keep(w):return bool(w) and w.isascii() and w.islower() and w.isalpha() and not ivtff.uncertain(w)
def rows(pages):
 out=[]
 for p in pages:
  for ln in p.lines:
   if ln.unit!='P':continue
   for i in range(1,len(ln.words)):
    a,b=ln.words[i-1:i+1]
    if keep(a) and keep(b):out.append((p.id,ln.id,i,cls(a),cls(b)))
 return out

def pos(i):return 0 if i==1 else 1 if i<=3 else 2 if i<=6 else 3
train=rows(corpus.split_pages('practice','zl')[0]); contexts=Counter(); base=Counter(); totals=Counter(); btot=Counter()
for p,l,i,a,b in train:
 j=pos(i);contexts[j,a,b]+=1;totals[j,a]+=1;base[j,b]+=1;btot[j]+=1

def gain(row):
 p,l,i,a,b=row;j=pos(i);return math.log((contexts[j,a,b]+1)/(totals[j,a]+K))-math.log((base[j,b]+1)/(btot[j]+K))

def assess(rs):
 gs=[gain(r) for r in rs];groups=defaultdict(list)
 for r,g in zip(rs,gs):groups[r[0]].append(g)
 keys=sorted(groups);rng=random.Random(29111);boot=[]
 for _ in range(2000):
  sampled=[rng.choice(keys) for i in keys];boot.append(sum(sum(groups[p]) for p in sampled)/sum(len(groups[p]) for p in sampled))
 boot.sort(); shuffled=[]
 for seed in range(100):
  rng=random.Random(seed); buckets=defaultdict(list)
  for r in rs:buckets[(r[0],pos(r[2]))].append(r[3])
  for v in buckets.values():rng.shuffle(v)
  vals=[]
  for p,l,i,a,b in rs:vals.append(gain((p,l,i,buckets[p,pos(i)].pop(),b)))
  shuffled.append(sum(vals)/len(vals))
 return {'tokens':len(rs),'folios':len(keys),'gain_nats':sum(gs)/len(gs),'bootstrap_95':[boot[49],boot[1949]],'permutation_gain_range':[min(shuffled),max(shuffled)],'permutation_mean':sum(shuffled)/len(shuffled),'observed_greater_permutations':sum(sum(gs)/len(gs)>v for v in shuffled)}
out={'training_tokens':len(train),'training_folios':len({r[0] for r in train}),'classes':CHARS+'+OTHER','results':{}}
ep={t:corpus.split_pages('practice',t)[1] for t in ('zl','it')}
lines={t:{(p.id,l.id):len(l.words) for p in ep[t] for l in p.lines if l.unit=='P'} for t in ep}
matched={k for k,v in lines['zl'].items() if lines['it'].get(k)==v}
rr={t:[r for r in rows(ep[t]) if (r[0],r[1]) in matched] for t in ep}
indices={t:{(r[0],r[1],r[2]):r for r in rr[t]} for t in rr}
common=indices['zl'].keys() & indices['it'].keys()
out['matched_equal_length_lines']=len(matched);out['both_witness_positions']=len(common)
out['both_classes_agree']=sum(indices['zl'][k][3:]==indices['it'][k][3:] for k in common)
for t in rr:out['results'][t]=assess(rr[t])
print(json.dumps(out,indent=2))
